function sqlExplain(sql){
  var r={select:[], from:'', joins:[], where:[], groupBy:'', orderBy:'', limit:null, valid:false, raw:sql};
  if(!sql) return r;
  var s=sql.replace(/--[^\n]*\n/g,' ').replace(/\s+/g,' ').trim();
  var m=s.match(/select\s+(.*?)\s+from\s+/i);
  if(m){ r.select=m[1].split(',').map(function(x){return x.trim();}).filter(Boolean); }
  var fm=s.match(/from\s+([`"']?\w+[`"']?)/i);
  if(fm) r.from=fm[1].replace(/[`"']/g,'');
  var jm=s.match(/join\s+([`"']?\w+[`"']?)(?:\s+(?!on\b)[`"']?\w+[`"']?)?\s+on\s+([^\s]+)\s*=\s*([^\s]+)/gi);
  if(jm){ for(var i=0;i<jm.length;i++){ var p=jm[i].match(/join\s+([`"']?\w+[`"']?)(?:\s+(?!on\b)[`"']?\w+[`"']?)?\s+on\s+([^\s]+)\s*=\s*([^\s]+)/i); if(p) r.joins.push({table:p[1].replace(/[`"']/g,''), on:p[2]+'='+p[3]}); } }
  var wm=s.match(/where\s+(.*?)(?:\s+group by|\s+order by|\s+limit|$)/i);
  if(wm){ var cond=wm[1].trim(); if(cond) r.where=cond.split(/\s+and\s+/i).map(function(x){return x.trim();}); }
  var gm=s.match(/group by\s+([^\s]+)/i); if(gm) r.groupBy=gm[1];
  var om=s.match(/order by\s+([^\s]+)/i); if(om) r.orderBy=om[1];
  var lm=s.match(/limit\s+(\d+)/i); if(lm) r.limit=parseInt(lm[1],10);
  r.valid = r.select.length>0 && !!r.from;
  return r;
}
